isión: {{ $asset->diagnosed_at?->translatedFormat('d M Y') ?? 'Sin diagnóstico' }}</p>@if(auth()->user()->isOperator())<form method="post" action="{{ route('assets.update',$asset) }}">@csrf @method('PATCH')<label for="asset-state-{{ $asset->id }}">Nuevo estado</label><select name="status" id="asset-state-{{ $asset->id }}">@foreach(['available','pending_review','quarantine','maintenance','missing'] as $s)<option value="{{ $s }}" @selected($asset->status===$s)>{{ config('turnolab.states')[$s] }}</option>@endforeach</select><label for="asset-notes-{{ $asset->id }}">Resultado o motivo</label><textarea name="notes" id="asset-notes-{{ $asset->id }}" required minlength="8" rows="2"></textarea><button class="button small">Guardar revisión</button></form>@endif</div></details></td></tr>@empty<tr><td colspan="5"><x-empty title="No encontramos equipos" text="Prueba otro nombre, código o filtro."/></td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $assets->links() }}</div></section><p class="help">ABC es ilustrativo en la demo. La clasificación definitiva se calculará con la frecuencia de solicitudes de la operación real.</p>@endsection